// src/components/SpendingPriority.js
import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import "./SpendingPriority.css";

function SpendingPriority({ formData, updateData }) {
  const navigate = useNavigate();
  const categories = formData.category || [];

  // Initialize slider values
  const [priorities, setPriorities] = useState({});

  useEffect(() => {
    const initial = {};
    categories.forEach(cat => {
      initial[cat] = formData.spendingPriority?.[cat] || 0;
    });
    setPriorities(initial);
  }, [categories, formData]);

  // Handle slider change
  const handleSliderChange = (cat, val) => {
    setPriorities(prev => ({ ...prev, [cat]: Number(val) }));
  };

  // Continue to BudgetLimits page
  const handleNext = () => {
    const selectedCategories = Object.keys(priorities).filter(cat => priorities[cat] >= 0);
    if (!selectedCategories.length) {
      alert("Please select at least one category");
      return;
    }
    updateData({ spendingPriority: priorities });
    navigate("/budget");
  };

  if (!categories.length) {
    return <p style={{ textAlign: "center", color: "red" }}>No income categories selected</p>;
  }

  return (
    <div className="spending-container">
      <h2 className="spending-title">Set Spending Priorities</h2>
      <div className="spending-grid">
        {categories.map(cat => (
          <div key={cat} className="spending-card">
            <h3 className="spending-name">{cat}</h3>
            <input
              type="range"
              min={0}
              max={5}
              value={priorities[cat]}
              onChange={e => handleSliderChange(cat, e.target.value)}
              className="spending-slider"
            />
            <p>Priority: {priorities[cat]}</p>
          </div>
        ))}
      </div>
      <button className="next-button" onClick={handleNext}>Continue</button>
    </div>
  );
}

export default SpendingPriority;
